'use client';

import React, { useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import styles from '@/styles/Header.module.css';

interface NavItem {
  id: string;
  label: string;
  icon: string;
  href: string;
}

const navItems: NavItem[] = [
  { id: 'trang-chu', label: 'Trang chủ', icon: '🏠', href: '/' },
  { id: 'de-thi', label: 'Đề thi', icon: '📝', href: '#de-thi' },
  { id: 'tu-vung', label: 'Từ vựng', icon: '📖', href: '#tu-vung' },
  { id: 'ngu-phap', label: 'Ngữ pháp', icon: '🔡', href: '#ngu-phap' },
];

export default function Header() {
  const [activeTab, setActiveTab] = useState<string>('trang-chu');
  const [indicatorStyle, setIndicatorStyle] = useState<{ left: number; width: number; opacity: number }>({
    left: 0,
    width: 0,
    opacity: 0,
  });

  const tabRefs = useRef<{ [key: string]: HTMLAnchorElement | null }>({});

  const updateIndicator = (tabId: string) => {
    const currentTabEl = tabRefs.current[tabId];
    if (currentTabEl) {
      setIndicatorStyle({
        left: currentTabEl.offsetLeft,
        width: currentTabEl.offsetWidth,
        opacity: 1,
      });
    }
  };

  useEffect(() => {
    updateIndicator(activeTab);

    const handleResize = () => {
      updateIndicator(activeTab);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [activeTab]);

  return (
    <header className={styles.header}>
      <div className={styles.headerContainer}>
        {/* Logo Section */}
        <Link href="/" className={styles.logoLink}>
          <div className={styles.logoIcon}>🎓</div>
          <div>
            <div className={styles.logoTitle}>
              TOEIC<span className={styles.logoTitleAccent}>GREEN</span>
            </div>
            <div className={styles.logoSub}>Mastery Learning</div>
          </div>
        </Link>

        {/* Sliding Pill Navigation with Smooth Sliding Background */}
        <div className={styles.navWrapper}>
          <nav className={styles.navContainer}>
            {/* Vùng background màu xanh chạy trượt theo tab */}
            <div
              className={styles.slidingIndicator}
              style={{
                transform: `translateX(${indicatorStyle.left}px)`,
                width: `${indicatorStyle.width}px`,
                opacity: indicatorStyle.opacity,
              }}
            />

            {navItems.map((item) => {
              const isActive = activeTab === item.id;
              return (
                <Link
                  key={item.id}
                  href={item.href}
                  ref={(el) => {
                    tabRefs.current[item.id] = el;
                  }}
                  onClick={() => {
                    setActiveTab(item.id);
                    updateIndicator(item.id);
                  }}
                  className={`${styles.navItem} ${isActive ? styles.navItemActive : ''}`}
                >
                  <span>{item.icon}</span>
                  <span>{item.label}</span>
                </Link>
              );
            })}
          </nav>
        </div>

        {/* Right Action: Auth buttons */}
        <div className={styles.actionsContainer}>
          <button className={styles.btnLogin}>
            Đăng nhập
          </button>

          <button className={styles.btnRegister}>
            Đăng ký
          </button>
        </div>
      </div>
    </header>
  );
}
